import{_ as n,a0 as r,w as i,s as a,I as s,x as l,a1 as p,A as e,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"DevOps 的彈性合作 | LCTT x X-CMD","titleTemplate":false,"description":"DevOps 的彈性合作 | LCTT (201608) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"DevOps 的彈性合作 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"DevOps 的彈性合作 | LCTT (201608) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201608/20160516 Scaling Collaboration in DevOps","title":"DevOps 的彈性合作","tag":"201608","desc":""},"relativePath":"201608/20160516 Scaling Collaboration in DevOps.md","filePath":"[post].md"}'),u={name:"201608/20160516 Scaling Collaboration in DevOps.md"};function v(f,t,D,m,O,b){const o=r("Link");return i(),a("div",null,[t[25]||(t[25]=s("h1",{id:"devops-的彈性合作",tabindex:"-1"},[l("DevOps 的彈性合作 "),s("a",{class:"header-anchor",href:"#devops-的彈性合作","aria-label":"Permalink to “DevOps 的彈性合作”"},"​")],-1)),t[26]||(t[26]=s("p",null,[s("img",{src:"http://devops.com/wp-content/uploads/2016/05/ScalingCollaboration.jpg",alt:""})],-1)),s("p",null,[t[1]||(t[1]=l("那些熟悉 DevOps 的人通常認為與其説 DevOps 是一種技術不如説是一種文化。在 DevOps 的有效實踐上需要一些特定的工具和經驗，但是 DevOps 成功的基礎在於企業內如何做好",-1)),p(o,{href:"http://devops.com/2014/12/15/four-strategies-supporting-devops-collaboration/"},{default:e(()=>[...t[0]||(t[0]=[l("團隊和個體協作",-1)])]),_:1}),t[2]||(t[2]=l("，從而可以讓事情更快、更高效而有效的完成。",-1))]),t[27]||(t[27]=s("p",null,"大多數的 DevOps 平台和工具都是以可擴展性為設計理念的。DevOps 環境通常運行在雲端，並且容易發生變化。對於DevOps 軟件來説，支持實時伸縮以解決衝突和摩擦是重要的。這同樣對於人的因素也是一樣的，但彈性合作卻是完全不同的。",-1)),t[28]||(t[28]=s("p",null,"跨企業協同是 DevOps 成功的關鍵。好的代碼和開發最終需要形成產品才能給用户帶來價值。公司所面臨的挑戰是如何做到無縫銜接和儘可能的提高速度及自動化水平，而不是犧牲質量或性能。企業如何才能流水線化代碼的開發和部署，同時保持維護工作的明晰、可控和合規？",-1)),t[29]||(t[29]=s("h3",{id:"新興趨勢",tabindex:"-1"},[l("新興趨勢 "),s("a",{class:"header-anchor",href:"#新興趨勢","aria-label":"Permalink to “新興趨勢”"},"​")],-1)),s("p",null,[t[4]||(t[4]=l("首先，我先提供一些背景，分享一些 ",-1)),p(o,{href:"https://451research.com/"},{default:e(()=>[...t[3]||(t[3]=[l("451 Research",-1)])]),_:1}),t[5]||(t[5]=l(" 在 DevOps 及其常規應用方面獲取的數據。雲、敏捷和Devops 的能力在今天是非常重要的，不管是理念還是現實。451 研究公司發現採用這些東西以及容器技術的企業在不斷增多，包括在生產環境中的大量使用。",-1))]),t[30]||(t[30]=s("p",null,"擁抱這些技術和方式有許多優點，比如提高靈活性和速度，降低成本，提高適應能力和可靠性，適應新的或新興的應用。據 451 Research 稱，團隊也面臨着一些障礙，包括缺乏熟悉其中所需的技能的人、這些新興技術的不成熟、成本和安全問題等。",-1)),s("p",null,[t[7]||(t[7]=l("在 “",-1)),p(o,{href:"https://451research.com/"},{default:e(()=>[...t[6]||(t[6]=[l("Voice of the Enterprise: SDI Q4 2015 survey",-1)])]),_:1}),t[8]||(t[8]=l("” 報告中，451 Research 發現超過一半的受訪者（57.1%）考慮他們稍晚些再採用，甚至會最後才採用這些新技術。另一方面，近半受訪者（48.3 %）認為自己是率先或早期的採用者。",-1))]),t[31]||(t[31]=d('<p>這些普遍性的情緒也表現在對其他問題的調查中。當問起容器的執行情況時，50.3% 的人表示這根本不在他們的計劃中。剩下 49.7% 的人則是在計劃、試點或積極使用容器技術。近 2/3（65.1%）的人表示，他們用敏捷開發方式來開發應用，但是隻有 39.6% 的人回應稱他們正在積極擁抱 DevOps。然而，敏捷軟件開發已經在行業內存在了多年，451 Research 注意到容器和 Devops 的採用率顯著提升，這是一個新的趨勢。</p><p>當被問及首要的三個 IT 痛點是什麼，被提及最多的是成本或預算、人員不足和遺留軟件問題。隨着企業向雲、DevOps、和容器等轉型，這些問題都需要加以解決，以及如何規劃技術和有效協作。</p><h3 id="當前狀況" tabindex="-1">當前狀況 <a class="header-anchor" href="#當前狀況" aria-label="Permalink to “當前狀況”">​</a></h3><p>軟件行業正處於急劇變化之中，這很大程度是由 DevOps 所推動的，它使得軟件開發變得越來越橫跨整個業務高度集成。軟件的開發變得不再閉門造車，而越來越體現協作和社交化的功能。</p><p>幾年還是在小説和展板中的理念和方法迅速成熟，成為了今天推動價值的主流技術和框架。企業依靠如敏捷、精益、虛擬化、雲計算、自動化和微服務等概念來簡化開發，同時使工作更加有效和高效。</p><p>為了適應和發展，企業需要完成一系列的關鍵任務。當今面臨的挑戰是如何加快發展的同時降低成本。團隊需要消除 IT 和其他業務之間存在的障礙，並在一個由技術驅動的競爭環境中提供更多有效的戰略合作。</p><p>敏捷、雲計算、DevOps 和容器在這個過程中起着重要的作用，而將它們連接在一起的是有效的合作。每一種技術和方法都提供了獨特的優勢，但真正的價值來自於團隊作為一個整體能夠進行規模協同，以及團隊所使用的工具和平台。成功的 DevOps 的實現也需要開發和 IT 運營團隊之外其他利益相關者的參與，包括安全、資料庫、存儲和業務隊伍。</p><h3 id="合作即平台" tabindex="-1">合作即平台 <a class="header-anchor" href="#合作即平台" aria-label="Permalink to “合作即平台”">​</a></h3><p>有一些在線的服務和平台，比如 Github 促進和增進了協作。這個在線平台的功能是一個在線代碼庫，但是所產生的價值遠超乎存儲代碼。</p>',9)),s("p",null,[t[10]||(t[10]=l("這樣一個",-1)),p(o,{href:"http://devops.com/events/analytics-of-collaboration-on-github/"},{default:e(()=>[...t[9]||(t[9]=[l("協作平台",-1)])]),_:1}),t[11]||(t[11]=l("之所以有助於開發人員和團隊合作，是因為它提供了一個可以分享和討論代碼和流程的社區。管理者可以監視進度和跟蹤將要發佈的代碼。開發人員在將實驗性的想法放到實際的產品環境中之前，可以在一個安全的環境中進行實驗，新的想法和實驗可以有效地與適當的團隊進行溝通。",-1))]),t[32]||(t[32]=s("p",null,"更加敏捷的開發和 DevOps 的關鍵之一是允許開發人員測試一些東西並快速收集相關的反饋。目標是生產高質量的代碼和功能，而不是浪費時間建立和管理基礎設施或者安排更多的會議來討論這個問題。比如 GitHub 平台，能夠更有效的和可擴展的協作是因為當參與者想要進行代碼審查時很方便。不需要嘗試協調和安排代碼審查會議，所以開發人員可以繼續工作而不被打斷，從而產生更大的生產力和工作滿意度。",-1)),t[33]||(t[33]=s("p",null,"Sendachi 的 Steven Anderson 指出，Github 是一個協作平台，但它也是一個和你一起工作的工具。這樣意味着它不僅可以幫助協作和持續集成，還影響了代碼質量。",-1)),t[34]||(t[34]=s("p",null,"合作平台的好處之一是，大型團隊的開發人員可以分解成更小的團隊，可以更有效地專注於特定的組件。它還提供了諸如文件共享這樣的代碼之外的功能，模糊了技術和非技術的貢獻，增加了協作和可見性。",-1)),t[35]||(t[35]=s("h3",{id:"合作是關鍵",tabindex:"-1"},[l("合作是關鍵 "),s("a",{class:"header-anchor",href:"#合作是關鍵","aria-label":"Permalink to “合作是關鍵”"},"​")],-1)),t[36]||(t[36]=s("p",null,"合作的重要性不言而喻。合作是 DevOps 文化的關鍵，也是在當今世界能夠進行敏捷開發並保持競爭優勢的決定因素。執行或管理支持以及內部傳道是很重要的。團隊還需要擁抱文化的轉變---邁向共同目標的跨職能部門的技能融合。",-1)),t[37]||(t[37]=s("p",null,"要建立起來這樣的文化，有效的合作是至關重要的。一個合作平台是彈性合作的必要組件，因為簡化了生產活動，並且減少了冗餘和嘗試，同時還產生了更高質量的結果。",-1)),t[38]||(t[38]=s("hr",null,null,-1)),s("p",null,[t[13]||(t[13]=l("via: ",-1)),p(o,{href:"http://devops.com/2016/05/16/scaling-collaboration-devops/"},{default:e(()=>[...t[12]||(t[12]=[l("http://devops.com/2016/05/16/scaling-collaboration-devops/",-1)])]),_:1})]),s("p",null,[t[17]||(t[17]=l("作者：",-1)),p(o,{href:"http://devops.com/author/tonybsg/"},{default:e(()=>[...t[14]||(t[14]=[l("TONY BRADLEY",-1)])]),_:1}),t[18]||(t[18]=l(" 譯者：",-1)),p(o,{href:"https://github.com/Bestony"},{default:e(()=>[...t[15]||(t[15]=[l("Bestony",-1)])]),_:1}),t[19]||(t[19]=l(" 校對：",-1)),p(o,{href:"https://github.com/wxy"},{default:e(()=>[...t[16]||(t[16]=[l("wxy",-1)])]),_:1})]),s("p",null,[t[22]||(t[22]=l("本文由 ",-1)),p(o,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[20]||(t[20]=[l("LCTT",-1)])]),_:1}),t[23]||(t[23]=l(" 原創編譯，",-1)),p(o,{href:"https://linux.cn/"},{default:e(()=>[...t[21]||(t[21]=[l("Linux中國",-1)])]),_:1}),t[24]||(t[24]=l(" 榮譽推出",-1))])])}const x=n(u,[["render",v]]);export{C as __pageData,x as default};
